def _load_one_plugin(
    self,
    ep: importlib.metadata.EntryPoint,
    invoke_on_load: bool,
    invoke_args: tuple[Any],
    invoke_kwds: dict[str, Any],
) -> Extension[T] | None:
    plugin = ep.load()
    if invoke_on_load:
        obj = plugin(*invoke_args, **invoke_kwds)
    else:
        obj = None
    return Extension(ep.name, ep, plugin, obj)
